import React, { useState, useEffect } from 'react';
import { machineApi } from '../api/client';
import {
  Sparkles,
  Sliders,
  Gauge,
  Thermometer,
  Zap,
  TrendingUp,
  AlertTriangle,
  CheckCircle2,
  Play,
  RotateCcw,
  Layers,
  Cpu,
  DollarSign,
  ShieldAlert,
} from 'lucide-react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const WhatIfSimulationPage = () => {
  // Simulation Input Controls State
  const [targetRpm, setTargetRpm] = useState(980);
  const [jetPressure, setJetPressure] = useState(4.8);
  const [ambientTemp, setAmbientTemp] = useState(32);
  const [yarnQuality, setYarnQuality] = useState('Combed Cotton 40s');
  const [deferredMaintDays, setDeferredMaintDays] = useState(0);
  const [selectedMachineId, setSelectedMachineId] = useState('ALL');
  const [machines, setMachines] = useState([]);

  useEffect(() => {
    fetchMachines();
  }, []);

  const fetchMachines = async () => {
    try {
      const res = await machineApi.getAll();
      if (res.data.success) {
        setMachines(res.data.data);
      }
    } catch (err) {
      console.error('Failed to fetch machines for simulation:', err);
    }
  };

  // Preset Scenario Handlers
  const applyPreset = (preset) => {
    switch (preset) {
      case 'rush':
        setTargetRpm(1150);
        setJetPressure(5.8);
        setAmbientTemp(36);
        setYarnQuality('Heavy Canvas Denim');
        setDeferredMaintDays(14);
        break;
      case 'eco':
        setTargetRpm(820);
        setJetPressure(4.0);
        setAmbientTemp(26);
        setYarnQuality('Combed Cotton 40s');
        setDeferredMaintDays(0);
        break;
      case 'life':
        setTargetRpm(750);
        setJetPressure(3.8);
        setAmbientTemp(24);
        setYarnQuality('Carded Cotton');
        setDeferredMaintDays(0);
        break;
      case 'heatwave':
        setTargetRpm(960);
        setJetPressure(4.6);
        setAmbientTemp(44);
        setYarnQuality('Polyester Blend');
        setDeferredMaintDays(7);
        break;
      default:
        resetSimulation();
    }
  };

  const resetSimulation = () => {
    setTargetRpm(980);
    setJetPressure(4.8);
    setAmbientTemp(32);
    setYarnQuality('Combed Cotton 40s');
    setDeferredMaintDays(0);
    setSelectedMachineId('ALL');
  };

  // Dynamic AI Simulation Calculations
  const baselineOutput = 14850;
  const rpmFactor = targetRpm / 980;
  const pressureFactor = jetPressure / 4.8;
  const tempFactor = ambientTemp > 35 ? (ambientTemp - 35) * 0.02 : 0;
  const deferredMaintFactor = deferredMaintDays * 0.015;

  // Predicted Metrics
  const predictedOutput = Math.round(baselineOutput * rpmFactor * (1 - tempFactor * 0.5));
  const outputChangePct = (((predictedOutput - baselineOutput) / baselineOutput) * 100).toFixed(1);

  const baselineFailureRisk = 4.2;
  const predictedFailureRisk = (
    baselineFailureRisk *
    Math.pow(rpmFactor, 1.8) *
    (1 + tempFactor * 1.5) *
    (1 + deferredMaintFactor)
  ).toFixed(1);

  const baselinePowerKwh = 1485;
  const predictedPowerKwh = Math.round(baselinePowerKwh * Math.pow(rpmFactor, 1.4) * pressureFactor);
  const powerCost = Math.round(predictedPowerKwh * 0.15); // $0.15 / kWh

  const baselineRulDays = 165;
  const predictedRulDays = Math.max(15, Math.round(baselineRulDays / (rpmFactor * (1 + tempFactor + deferredMaintFactor))));

  // Generate AI Recommendation Text
  const getAiPrescription = () => {
    if (targetRpm > 1100 && ambientTemp > 38) {
      return {
        type: 'critical',
        title: '⚠️ CRITICAL RISK: Severe Motor Thermal Overheating Detected',
        text: `Operating at ${targetRpm} RPM under ${ambientTemp}°C ambient heat increases failure probability to ${predictedFailureRisk}%! Main motor drive bearings are projected to fail within ${predictedRulDays} days. Reduce RPM below 1,020 immediately.`,
      };
    } else if (targetRpm > 1050 || deferredMaintDays > 10) {
      return {
        type: 'warning',
        title: '⚡ MODERATE RISK: High Wear Rate Advisory',
        text: `Target output increases by +${outputChangePct}%, but deferred maintenance (+${deferredMaintDays} days) elevates vibration stress on reed and shuttleless mechanisms. AI recommends scheduling lube service within 5 days.`,
      };
    } else if (targetRpm < 850) {
      return {
        type: 'eco',
        title: '🍃 ECO OPTIMAL: Energy Saving & Maximum RUL Mode',
        text: `Energy consumption decreases by ${Math.abs(Math.round(((predictedPowerKwh - baselinePowerKwh) / baselinePowerKwh) * 100))}% with RUL extended to ${predictedRulDays} days. Ideal for low-urgency yarn runs.`,
      };
    } else {
      return {
        type: 'success',
        title: '✅ STABLE OPERATION: Optimal Performance Range',
        text: `Simulated parameters are within nominal safety bounds. Predicted fabric yield is ${predictedOutput.toLocaleString()} meters/day with an acceptable failure risk of ${predictedFailureRisk}%.`,
      };
    }
  };

  const aiPrescription = getAiPrescription();

  // Comparison Bar Chart Data
  const chartData = {
    labels: ['Fabric Yield (Meters/10)', 'Failure Risk (%)', 'Power Use (kWh/10)', 'RUL Days'],
    datasets: [
      {
        label: 'Baseline Operational State',
        data: [1485, 4.2, 148, 165],
        backgroundColor: '#4F46E5',
        borderRadius: 4,
      },
      {
        label: 'Simulated What-If State',
        data: [Math.round(predictedOutput / 10), parseFloat(predictedFailureRisk), Math.round(predictedPowerKwh / 10), predictedRulDays],
        backgroundColor: predictedFailureRisk > 15 ? '#E11D48' : '#059669',
        borderRadius: 4,
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'top',
        align: 'end',
        labels: { color: '#0F172A', font: { family: 'Plus Jakarta Sans', size: 12, weight: '800' } },
      },
    },
    scales: {
      x: { ticks: { color: '#0F172A', font: { family: 'Plus Jakarta Sans', size: 11, weight: '800' } } },
      y: { ticks: { color: '#0F172A', font: { family: 'Plus Jakarta Sans', size: 11, weight: '800' } } },
    },
  };

  return (
    <div>
      {/* Header */}
      <div className="page-header">
        <div className="page-title-group">
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <h1>What-If AI Simulation Engine</h1>
            <span className="badge badge-high" style={{ background: 'var(--status-critical-bg)', color: 'var(--status-critical)', border: '1px solid rgba(124, 58, 237, 0.3)' }}>
              <Sparkles size={14} /> AI PREDICTIVE TWIN
            </span>
          </div>
          <p>Simulate Operating Speed, Air Jet Pressure, & Temperature Scenarios to Predict Yield & Asset Risk</p>
        </div>

        <button className="btn btn-secondary" onClick={resetSimulation}>
          <RotateCcw size={16} /> Reset Simulation Parameters
        </button>
      </div>

      {/* Preset What-If Scenario Quick Buttons */}
      <div style={{ display: 'flex', gap: '0.85rem', flexWrap: 'wrap', marginBottom: '1.75rem' }}>
        <button className="btn btn-secondary btn-sm" onClick={() => applyPreset('rush')} style={{ borderLeft: '4px solid var(--status-maintenance)' }}>
          🚀 Rush Order Max Throughput
        </button>
        <button className="btn btn-secondary btn-sm" onClick={() => applyPreset('eco')} style={{ borderLeft: '4px solid var(--status-running)' }}>
          🍃 Eco Energy-Saver Mode
        </button>
        <button className="btn btn-secondary btn-sm" onClick={() => applyPreset('life')} style={{ borderLeft: '4px solid var(--accent-primary)' }}>
          🛡️ Max Asset Lifespan Mode
        </button>
        <button className="btn btn-secondary btn-sm" onClick={() => applyPreset('heatwave')} style={{ borderLeft: '4px solid var(--status-idle)' }}>
          ☀️ Summer Heatwave Operating Mode
        </button>
      </div>

      {/* Main Grid: Control Panel + Live Predictions */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(380px, 1fr))', gap: '1.75rem', marginBottom: '1.75rem' }}>
        {/* Left Panel: Parameter Control Sliders */}
        <div className="glass-card" style={{ padding: '1.75rem', display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
          <div style={{ borderBottom: '1px solid var(--border-subtle)', paddingBottom: '0.85rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <h3 style={{ fontSize: '1.1rem', fontWeight: '800', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <Sliders size={20} style={{ color: 'var(--accent-primary)' }} /> What-If Parameter Controls
            </h3>
            <span style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', fontWeight: '800' }}>Live Slider Input</span>
          </div>

          {/* Machine Target Selector */}
          <div className="form-group">
            <label>Target Machine Asset Scope</label>
            <select className="form-control" value={selectedMachineId} onChange={(e) => setSelectedMachineId(e.target.value)}>
              <option value="ALL">Entire Fleet (All 13 Weaving Looms)</option>
              {machines.map((m) => (
                <option key={m._id || m.machineId} value={m.machineId}>
                  {m.machineId} - {m.assetName} ({m.factoryName})
                </option>
              ))}
            </select>
          </div>

          {/* Slider 1: Target Speed (RPM) */}
          <div className="form-group">
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.88rem', fontWeight: '800' }}>
              <span style={{ color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                <Gauge size={16} style={{ color: 'var(--accent-primary)' }} /> Target Weaving Speed (RPM)
              </span>
              <span style={{ color: 'var(--accent-primary)', fontSize: '1.05rem' }}>{targetRpm} RPM</span>
            </div>
            <input
              type="range"
              min="600"
              max="1200"
              step="10"
              value={targetRpm}
              onChange={(e) => setTargetRpm(Number(e.target.value))}
              style={{ width: '100%', marginTop: '0.4rem', cursor: 'pointer', accentColor: 'var(--accent-primary)' }}
            />
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.75rem', color: '#334155', fontWeight: '700' }}>
              <span>600 RPM (Low)</span>
              <span>980 RPM (Baseline)</span>
              <span>1200 RPM (Max)</span>
            </div>
          </div>

          {/* Slider 2: Air Jet / Pump Pressure */}
          <div className="form-group">
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.88rem', fontWeight: '800' }}>
              <span style={{ color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                <Zap size={16} style={{ color: 'var(--status-running)' }} /> Nozzle Air / Water Pressure (Bar)
              </span>
              <span style={{ color: 'var(--status-running)', fontSize: '1.05rem' }}>{jetPressure} Bar</span>
            </div>
            <input
              type="range"
              min="2.5"
              max="6.5"
              step="0.1"
              value={jetPressure}
              onChange={(e) => setJetPressure(Number(e.target.value))}
              style={{ width: '100%', marginTop: '0.4rem', cursor: 'pointer', accentColor: 'var(--status-running)' }}
            />
          </div>

          {/* Slider 3: Ambient Temperature */}
          <div className="form-group">
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.88rem', fontWeight: '800' }}>
              <span style={{ color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                <Thermometer size={16} style={{ color: 'var(--status-maintenance)' }} /> Factory Ambient Temp (°C)
              </span>
              <span style={{ color: 'var(--status-maintenance)', fontSize: '1.05rem' }}>{ambientTemp}°C</span>
            </div>
            <input
              type="range"
              min="20"
              max="48"
              step="1"
              value={ambientTemp}
              onChange={(e) => setAmbientTemp(Number(e.target.value))}
              style={{ width: '100%', marginTop: '0.4rem', cursor: 'pointer', accentColor: 'var(--status-maintenance)' }}
            />
          </div>

          {/* Slider 4: Deferred Maintenance Days */}
          <div className="form-group">
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.88rem', fontWeight: '800' }}>
              <span style={{ color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                <ShieldAlert size={16} style={{ color: 'var(--status-idle)' }} /> Deferred Service Offset
              </span>
              <span style={{ color: 'var(--status-idle)', fontSize: '1.05rem' }}>+{deferredMaintDays} Days</span>
            </div>
            <input
              type="range"
              min="0"
              max="30"
              step="1"
              value={deferredMaintDays}
              onChange={(e) => setDeferredMaintDays(Number(e.target.value))}
              style={{ width: '100%', marginTop: '0.4rem', cursor: 'pointer', accentColor: 'var(--status-idle)' }}
            />
          </div>
        </div>

        {/* Right Panel: Real-Time AI Predictions Cards */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
          {/* AI Prescription Banner */}
          <div
            style={{
              padding: '1.25rem 1.5rem',
              borderRadius: 'var(--radius-md)',
              background:
                aiPrescription.type === 'critical'
                  ? 'var(--status-maintenance-bg)'
                  : aiPrescription.type === 'warning'
                  ? 'var(--status-idle-bg)'
                  : aiPrescription.type === 'eco'
                  ? 'var(--status-running-bg)'
                  : 'var(--status-running-bg)',
              border:
                aiPrescription.type === 'critical'
                  ? '1px solid rgba(225, 29, 72, 0.4)'
                  : aiPrescription.type === 'warning'
                  ? '1px solid rgba(217, 119, 6, 0.4)'
                  : '1px solid rgba(5, 150, 105, 0.4)',
            }}
          >
            <div style={{ fontSize: '1.05rem', fontWeight: '800', color: '#0F172A', marginBottom: '0.4rem' }}>
              {aiPrescription.title}
            </div>
            <div style={{ fontSize: '0.9rem', color: '#1E293B', fontWeight: '700', lineHeight: 1.4 }}>
              {aiPrescription.text}
            </div>
          </div>

          {/* Predicted Metrics 2x2 Grid */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '1.25rem' }}>
            <div className="glass-card" style={{ padding: '1.25rem' }}>
              <div style={{ fontSize: '0.8rem', color: '#334155', fontWeight: '800' }}>PREDICTED YIELD</div>
              <div style={{ fontSize: '1.75rem', fontWeight: '900', color: '#0F172A', margin: '4px 0' }}>
                {predictedOutput.toLocaleString()} <span style={{ fontSize: '0.85rem', fontWeight: '700' }}>M/day</span>
              </div>
              <div style={{ fontSize: '0.8rem', fontWeight: '800', color: outputChangePct >= 0 ? 'var(--status-running)' : 'var(--status-maintenance)' }}>
                {outputChangePct >= 0 ? `+${outputChangePct}% vs Baseline` : `${outputChangePct}% vs Baseline`}
              </div>
            </div>

            <div className="glass-card" style={{ padding: '1.25rem' }}>
              <div style={{ fontSize: '0.8rem', color: '#334155', fontWeight: '800' }}>FAILURE PROBABILITY</div>
              <div style={{ fontSize: '1.75rem', fontWeight: '900', color: predictedFailureRisk > 15 ? 'var(--status-maintenance)' : 'var(--status-running)', margin: '4px 0' }}>
                {predictedFailureRisk}%
              </div>
              <div style={{ fontSize: '0.8rem', fontWeight: '800', color: predictedFailureRisk > 15 ? 'var(--status-maintenance)' : 'var(--status-running)' }}>
                {predictedFailureRisk > 15 ? 'High Risk Anomaly' : 'Normal Operational Risk'}
              </div>
            </div>

            <div className="glass-card" style={{ padding: '1.25rem' }}>
              <div style={{ fontSize: '0.8rem', color: '#334155', fontWeight: '800' }}>PREDICTED RUL</div>
              <div style={{ fontSize: '1.75rem', fontWeight: '900', color: 'var(--accent-primary)', margin: '4px 0' }}>
                {predictedRulDays} <span style={{ fontSize: '0.85rem', fontWeight: '700' }}>Days</span>
              </div>
              <div style={{ fontSize: '0.8rem', fontWeight: '800', color: '#334155' }}>
                Remaining Useful Life
              </div>
            </div>

            <div className="glass-card" style={{ padding: '1.25rem' }}>
              <div style={{ fontSize: '0.8rem', color: '#334155', fontWeight: '800' }}>ENERGY COST / DAY</div>
              <div style={{ fontSize: '1.75rem', fontWeight: '900', color: '#0F172A', margin: '4px 0' }}>
                ${powerCost} <span style={{ fontSize: '0.85rem', fontWeight: '700' }}>/day</span>
              </div>
              <div style={{ fontSize: '0.8rem', fontWeight: '800', color: '#334155' }}>
                {predictedPowerKwh} kWh Consumed
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Comparison Chart Section */}
      <div className="glass-card" style={{ padding: '1.75rem' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
          <div>
            <h3 style={{ fontSize: '1.1rem', fontWeight: '800', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <TrendingUp size={20} style={{ color: 'var(--accent-primary)' }} /> Baseline vs Simulated What-If Comparison
            </h3>
            <span style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', fontWeight: '700' }}>
              Comparative Analysis Across Yield, Risk %, Power (kWh), & Remaining Life
            </span>
          </div>
        </div>
        <div style={{ height: '260px', width: '100%' }}>
          <Bar data={chartData} options={chartOptions} />
        </div>
      </div>
    </div>
  );
};

export default WhatIfSimulationPage;
